    91→  @Nullable
    92→  static ColumnCapabilities getColumnCapabilities(
    93→      final RowSignature rowSignature,
    94→      final String columnName
    95→  )
    96→  {
    97→    if (ColumnHolder.TIME_COLUMN_NAME.equals(columnName)) {
    98→      // TIME_COLUMN_NAME is handled specially; override the provided rowSignature.
    99→      return ColumnCapabilitiesImpl.createSimpleNumericColumnCapabilities(ValueType.LONG);
   100→    } else {
   101→      final ValueType valueType = rowSignature.getColumnType(columnName).orElse(null);
   102→
   103→
   104→      if (valueType != null) {
   105→        if (valueType.isNumeric()) {
   106→          return ColumnCapabilitiesImpl.createSimpleNumericColumnCapabilities(valueType);
   107→        }
   108→
   109→        if (valueType.isArray()) {
   110→          return ColumnCapabilitiesImpl.createSimpleArrayColumnCapabilities(valueType);
   111→        }
   112→
   113→        // Do _not_ set isDictionaryEncoded or hasBitmapIndexes, because Row-based columns do not have those things.
   114→        // Do not set hasMultipleValues, because even though we might return multiple values, setting it affirmatively
   115→        // causes expression selectors to always treat us as arrays, so leave as unknown
   116→        return new ColumnCapabilitiesImpl()
   117→            .setType(valueType)
   118→            .setDictionaryValuesUnique(false)
   119→            .setDictionaryValuesSorted(false);
   120→      } else {
   121→        return null;
   122→      }
   123→    }
   124→  }
