   134→  private DimensionSelector makeDimensionSelectorUndecorated(DimensionSpec dimensionSpec)
   135→  {
   136→    final String dimension = dimensionSpec.getDimension();
   137→    final ExtractionFn extractionFn = dimensionSpec.getExtractionFn();
   138→
   139→    if (ColumnHolder.TIME_COLUMN_NAME.equals(dimensionSpec.getDimension())) {
   140→      if (extractionFn == null) {
   141→        throw new UnsupportedOperationException("time dimension must provide an extraction function");
