   144→      final ToLongFunction<T> timestampFunction = adapter.timestampFunction();
   145→
   146→      return new BaseSingleValueDimensionSelector()
   147→      {
   148→        @Override
   149→        protected String getValue()
   150→        {
   151→          return extractionFn.apply(timestampFunction.applyAsLong(supplier.get()));
